import os,sys,json,subprocess,hashlib
from pathlib import Path
def cmd(a,t=12):
 try:
  p=subprocess.run(a,capture_output=True,text=True,timeout=t)
  return {'status':p.returncode,'out':p.stdout.strip()[:1000]}
 except Exception as e: return {'error':type(e).__name__}
def info(name):
 x=Path(name)
 if x.is_symlink(): return {'kind':'link','dest':str(x.resolve(strict=False))}
 if not x.exists(): return {'kind':'missing'}
 try:
  t=x.stat()
  return {'kind':'directory' if x.is_dir() else 'file','uid':t.st_uid,'mode':oct(t.st_mode&0o7777),'bytes':t.st_size}
 except Exception:return {'kind':'inaccessible'}
